<?php
use App\Services\AlumniRegistrationService; use Illuminate\Validation\Rule; use Livewire\Attributes\Layout; use Livewire\Attributes\Title; use Livewire\Component; use Livewire\WithFileUploads;
new #[Layout('layouts.public'), Title('Daftar Alumni Bercerita')] class extends Component { use WithFileUploads; public string $nama_lengkap='', $tahun_kelulusan='', $whatsapp='', $domisili='', $status='', $platform_sosial='instagram', $username_instagram='', $link_instagram='', $username_tiktok='', $link_tiktok=''; public mixed $video=null; public bool $keaslian=false,$persetujuan_publikasi=false,$patuh_ketentuan=false; public function mount(): void {} protected function rules(): array { return ['nama_lengkap'=>['required','max:150'],'tahun_kelulusan'=>['required','integer'],'whatsapp'=>['required','max:30'],'domisili'=>['required','max:150'],'status'=>['required',Rule::in(['Pelajar','Mahasiswa','Bekerja','Lainnya'])],'platform_sosial'=>['required',Rule::in(['instagram','tiktok','keduanya'])],'video'=>['required','file','mimetypes:video/mp4,video/quicktime','max:102400'],'keaslian'=>['accepted'],'persetujuan_publikasi'=>['accepted'],'patuh_ketentuan'=>['accepted']]; } public function save(AlumniRegistrationService $registration): void { $data=$this->validate(); $peserta=$registration->register(collect($data)->except(['video','keaslian','persetujuan_publikasi','patuh_ketentuan'])->all(),$this->video); flash()->success('Data berhasil disimpan.'); $this->redirectRoute('alumni.success',['kode'=>$peserta->kode_registrasi],navigate:true); }}; ?>
<main class="min-h-screen bg-slate-50 py-10"><div class="mx-auto max-w-2xl px-4"><a href="{{ route('home') }}" class="text-sm text-amber-700">← Alumni Bercerita</a><h1 class="mt-4 text-3xl font-bold">Pendaftaran karya</h1><form wire:submit="save" class="mt-6 space-y-5 rounded-2xl bg-white p-6 shadow-sm"><div class="grid gap-4 sm:grid-cols-2"><flux:input wire:model="nama_lengkap" label="Nama lengkap" required/><flux:input wire:model="tahun_kelulusan" label="Tahun kelulusan" type="number" required/><flux:input wire:model="whatsapp" label="Nomor WhatsApp" required/><flux:input wire:model="domisili" label="Domisili" required/></div><flux:select wire:model="status" label="Status"><option value="">Pilih status</option><option>Pelajar</option><option>Mahasiswa</option><option>Bekerja</option><option>Lainnya</option></flux:select><flux:select wire:model="platform_sosial" label="Platform"><option value="instagram">Instagram</option><option value="tiktok">TikTok</option><option value="keduanya">Instagram & TikTok</option></flux:select><flux:input wire:model="video" label="Video asli MP4/MOV (maks. 100 MB)" type="file" accept="video/mp4,video/quicktime" required/><p wire:loading wire:target="video" class="text-sm text-amber-700">Mengunggah video…</p><flux:checkbox wire:model="keaslian" label="Saya menyatakan karya ini asli."/><flux:checkbox wire:model="persetujuan_publikasi" label="Saya menyetujui publikasi karya."/><flux:checkbox wire:model="patuh_ketentuan" label="Saya mematuhi ketentuan program."/><flux:button type="submit" variant="primary" wire:loading.attr="disabled" wire:target="save,video"><span wire:loading.remove wire:target="save">Kirim pendaftaran</span><span wire:loading wire:target="save">Menyimpan…</span></flux:button></form></div></main>
